python3 -c "
import re
with open('/tmp/quarterly_unpack/word/document.xml','r',encoding='utf-8') as f:
    content = f.read()
paras = re.findall(r'<w:p>(.*?)</w:p>', content, re.S)
for i, p in enumerate(paras):
    texts = re.findall(r'<w:t[^>]*>(.*?)</w:t>', p, re.S)
    joined = ''.join(texts)
    # collect rPr details
    rprs = re.findall(r'<w:rPr>(.*?)</w:rPr>', p, re.S)
    details = set()
    for r in rprs:
        if '<w:b' in r: details.add('bold')
        if 'w:sz w:val=' in r:
            m = re.search(r'<w:sz w:val=\"(\d+)\"', r)
            if m: details.add('sz='+m.group(1))
        if '<w:u ' in r: details.add('underline')
        fm = re.findall(r'w:ascii=\"([^\"]+)\"', r)
        if fm: details.add('font='+fm[0])
    print(f'[{i}] {details} :: {joined!r}'[:200])
"
